INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Independent generation of sequence elements by motor cortex',2021,'Nature Neuroscience','10.1038/s41593-021-00831-7','Experimental','RNN','motor cortex, sequence generation, population dynamics, movement preparation, go cue','Shows that motor cortex generates sequential movements as independent elements rather than fused chunks, using separate preparatory states for each movement. RNN models trained to generate the same muscle activity patterns replicate the observed population dynamics.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Recurrent network models of sequence generation and memory',2016,'Neuron','10.1016/j.neuron.2016.02.009','Theoretical','RNN','neural sequences, recurrent networks, sequence generation, temporal structure, memory','Reviews how recurrent neural network models explain neural sequence generation observed across cortex, hippocampus, and basal ganglia, identifying canonical circuit mechanisms for temporal sequence production with direct AI applications.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Groundbreaking study reveals surprising parallels between biological and artificial intelligence in social interaction',2025,'Nature','10.1038/s41586-025-08729-3','Experimental','Mixed','social interaction, biological intelligence, AI parallels, UCLA, fMRI, social cognition','Landmark UCLA study revealing that biological and artificial neural networks converge on similar computational strategies when processing social interactions, extending the AI-brain parallel from sensory processing to higher-order social cognition.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Deep Neural Networks in Computational Neuroscience',2018,'bioRxiv','10.1101/133504','Review','CNN','computational neuroscience, DNNs, visual cortex, auditory cortex, review, biological modeling','Comprehensive review of how deep neural networks are used as computational models of sensory cortex, covering visual, auditory, and somatosensory systems, and discussing the opportunities and limitations of this modeling approach.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Deep Learning in Biological, Computer, and Neuromorphic Systems',2019,'Frontiers in Computational Neuroscience','10.3389/fncom.2019.00011','Review','Mixed','deep learning, biological systems, neuromorphic, perceptual learning, editorial','Editorial review covering the intersection of deep learning with biological neural systems and neuromorphic computing, highlighting key parallels and distinguishing principles across computational, biological, and hardware implementations.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Convergence of Artificial Intelligence and Neuroscience towards the Diagnosis of Neurological Disorders',2023,'Sensors','10.3390/s23063062','Review','Mixed','neurological disorders, AI diagnosis, EEG, fMRI, deep learning, clinical neuroscience','Reviews the convergence of AI and neuroscience for clinical neurological diagnosis, demonstrating how AI architectures derived from neuroscience principles improve diagnostic performance for epilepsy, Alzheimer disease, and Parkinson disease.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('The Role of Biology in Deep Learning',2022,'arXiv','10.48550/arXiv.2209.04425','Experimental','Sparse Autoencoder','sparse representations, weight sparsity, pruning, catastrophic forgetting, active dendrites','Investigates the role of biological sparsity principles in deep learning, finding that biologically-inspired sparsity improves robustness and reduces catastrophic forgetting without sacrificing accuracy.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Continual Learning Benefits from Multiple Sleep Stages: NREM, REM, and Synaptic Downscaling',2022,'IJCNN','10.1109/IJCNN55064.2022.9891965','Computational','Continual Learning','continual learning, NREM, REM, synaptic downscaling, sleep stages, forgetting','Demonstrates that implementing multiple distinct sleep stages in artificial networks produces better continual learning performance than any single stage alone, mirroring the multiphase biological sleep architecture.');
INSERT INTO paper (title, publication_year, journal, doi, methodology_type, ai_architecture_ref, keywords, abstract_summary) VALUES ('Investigating Echo State Network Performance with Biologically-Inspired Hierarchical Network Structure',2022,'IJCNN','10.1109/IJCNN55064.2022.9892248','Computational','RNN','echo state network, hierarchical structure, biological inspiration, reservoir computing, temporal tasks','Investigates how imposing biologically-inspired hierarchical connectivity on echo state networks affects computational performance on temporal tasks, finding improvements in memory capacity consistent with cortical hierarchical organization.');
